-- #140 탈퇴 (ADR-0069 decision 1 #57-15…#57-18, decision 3 #37-15…#37-17, decision 4 #140 rows and
-- decision 7; owner decisions 2026-10-23 on ADR-0085 결과 5 and on ADR-0086's 결과 4 — (2차) and
-- (3차); ADR-0086). Generated by `drizzle-kit generate`, then hand-edited where marked: this header
-- and the tail. The snapshot is as generated.
-- Self-contained and additive on #139's 0042: no row changes.
--
-- - ledger_entry_type: CLOSURE_FORFEIT ('탈퇴 소멸', #57-16), added at the end with ADD VALUE — so
--   nothing in this batch names it as the enum (55P04, migration 0014): the functions below compare
--   `type::text` in bodies that run after the batch commits.
-- - profiles.closed_at: when the member closed the account; profiles.nickname is null exactly then
--   (profiles_closed_check, which also keeps a closed account's 소개 and image empty and its role
--   `user`). The public items go at once (#37-16); the row stays — the ledger, the orders and every
--   record name the account (RESTRICT).
-- - ledger_entries_account_closure_unique: one forfeiture per closed account (its entry refers to
--   the account itself, ref `account_closure`).
-- - approval_requests_decision_check is replaced: a rejection may name no decider — the closure's
--   (owner decision 2026-10-23: a pending account restriction request about the member is closed
--   as rejected, reason '탈퇴', at the closure). Every other decision still names its admin, and the
--   trigger below allows that rejection for such a request only.
ALTER TYPE "public"."ledger_entry_type" ADD VALUE 'CLOSURE_FORFEIT';--> statement-breakpoint
ALTER TABLE "approval_requests" DROP CONSTRAINT "approval_requests_decision_check";--> statement-breakpoint
ALTER TABLE "profiles" ALTER COLUMN "nickname" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "profiles" ADD COLUMN "closed_at" timestamp (3) with time zone;--> statement-breakpoint
CREATE UNIQUE INDEX "ledger_entries_account_closure_unique" ON "ledger_entries" USING btree ("ref_id") WHERE "ledger_entries"."ref_type" = 'account_closure';--> statement-breakpoint
ALTER TABLE "approval_requests" ADD CONSTRAINT "approval_requests_decision_check" CHECK (("approval_requests"."status"::text IN ('pending', 'retracted')) = ("approval_requests"."decided_at" IS NULL) AND ("approval_requests"."decided_at" IS NULL) = ("approval_requests"."decision_reason" IS NULL) AND ("approval_requests"."decided_by" IS NULL OR "approval_requests"."decided_at" IS NOT NULL) AND ("approval_requests"."decided_by" IS NOT NULL OR "approval_requests"."status"::text <> 'approved') AND ("approval_requests"."status"::text = 'retracted') = ("approval_requests"."retracted_at" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_closed_check" CHECK (("profiles"."nickname" IS NULL) = ("profiles"."closed_at" IS NOT NULL) AND ("profiles"."closed_at" IS NULL OR ("profiles"."bio" IS NULL AND "profiles"."image_id" IS NULL AND "profiles"."role" = 'user')));--> statement-breakpoint
-- Hand-edited: a profile is created open, and a closed one never changes again (#57-17: no
-- restoration; #37-16: the public items stay gone) — whoever writes. Closing is one UPDATE that
-- sets closed_at and empties the nickname, the 소개 and the image together (profiles_closed_check).
-- TRUNCATE fires no row trigger.
CREATE FUNCTION profiles_keep_closed() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.closed_at IS NOT NULL THEN
      RAISE EXCEPTION 'profile % must be created open', NEW.user_id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.closed_at IS NOT NULL THEN
    RAISE EXCEPTION 'account % was closed at %: its profile never changes again', OLD.user_id,
      OLD.closed_at
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER profiles_keep_closed
  BEFORE INSERT OR UPDATE ON "profiles"
  FOR EACH ROW EXECUTE FUNCTION profiles_keep_closed();--> statement-breakpoint
-- Hand-edited: at the commit that closes an account, the closure is whole (#57-18 «식별 정보는 곧바로
-- 지운다», #57-16 «소멸»): no session and no sign-in method (password, social links) are left, nor a
-- password-reset token of better-auth's (`verification`, `reset-password:<token>` naming the
-- account — it would give the account a password again), its verified number
-- (`phone_verifications`; the code-send records stay, ADR-0070 2차 답 1), watchlist and search
-- history, interest categories or a nickname hold naming it; the profile keeps no time zone (owner
-- decision 2026-10-23 (3차) 6: the private setting goes too — NULL, "follow the browser", migration
-- 0022), and every watch the closure deleted has its unwatch event (owner decision 2026-10-23
-- (2차) 2: the watch history, kept for metrics (ADR-0064), ends each watch — within one (account,
-- market) the event ids are in commit order, so the last one is an unwatch); the balance is 0 (the
-- forfeiture's entry took it there); `user` keeps no address, name or photo — the address is the
-- placeholder `closed_<id>@` + NO_EMAIL_DOMAIN of @buddha/shared (`closedAccountEmail`, freed for a
-- new sign-up), the name better-auth's empty AUTH_USER_NAME; and no account restriction request
-- about the member waits (owner decision 2026-10-23: closed as rejected). Deferred, so the closure
-- may delete and write in any order inside its transaction. What stays is #57-18's to keep: the
-- ledger, orders, fills, positions, watch events, consent records, posts, comments, likes, reports
-- and actions, the media rows of posts and the code-send records. NEW is the row the closing
-- UPDATE wrote, which never changes again (profiles_keep_closed).
CREATE FUNCTION profiles_closed_completely() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  kept text;
BEGIN
  SELECT CASE
    WHEN EXISTS (SELECT FROM "session" WHERE "user_id" = NEW.user_id) THEN 'a session'
    WHEN EXISTS (SELECT FROM "account" WHERE "user_id" = NEW.user_id) THEN 'a sign-in method'
    WHEN EXISTS (SELECT FROM "verification"
                  WHERE "identifier" LIKE 'reset-password:%' AND "value" = NEW.user_id)
      THEN 'a password reset'
    WHEN EXISTS (SELECT FROM "phone_verifications" WHERE "user_id" = NEW.user_id)
      THEN 'its verified number'
    WHEN EXISTS (SELECT FROM "market_watches" WHERE "user_id" = NEW.user_id) THEN 'its watchlist'
    WHEN EXISTS (SELECT FROM "market_searches" WHERE "user_id" = NEW.user_id)
      THEN 'its search history'
    WHEN EXISTS (SELECT FROM "profile_interest_categories" WHERE "user_id" = NEW.user_id)
      THEN 'its interest categories'
    WHEN EXISTS (SELECT FROM "nickname_holds" WHERE "user_id" = NEW.user_id)
      THEN 'a nickname hold of its own'
    WHEN NEW.time_zone IS NOT NULL THEN 'its time zone'
    WHEN EXISTS (SELECT FROM "market_watch_events" e
                  WHERE e."user_id" = NEW.user_id AND e."action" = 'watch'
                    AND NOT EXISTS (SELECT FROM "market_watch_events" l
                                     WHERE l."user_id" = e."user_id"
                                       AND l."market_id" = e."market_id" AND l."id" > e."id"))
      THEN 'a watch with no unwatch event'
    WHEN EXISTS (SELECT FROM "balances"
                  WHERE "user_id" = NEW.user_id AND ("available_coin" <> 0 OR "locked_coin" <> 0))
      THEN 'Coin'
    WHEN NOT EXISTS (SELECT FROM "user"
                      WHERE "id" = NEW.user_id
                        AND "email" = 'closed_' || NEW.user_id || '@noemail.buddha.local'
                        AND "name" = '' AND "image" IS NULL)
      THEN 'its address, name or photo'
    WHEN EXISTS (SELECT FROM "approval_requests" r
                  WHERE r."status" = 'pending'
                    AND ((r."kind" = 'account_restriction' AND r."target_type" = 'user'
                          AND r."target_id" = NEW.user_id)
                      OR (r."kind" IN ('account_restriction_shorten', 'account_restriction_lift',
                                       'account_restriction_cancel')
                          AND r."target_type" = 'moderation_action'
                          AND EXISTS (SELECT FROM "moderation_actions" a
                                       WHERE a."id"::text = r."target_id"
                                         AND a."user_id" = NEW.user_id))))
      THEN 'a request about it waiting'
  END INTO kept;
  IF kept IS NOT NULL THEN
    RAISE EXCEPTION 'account % was closed keeping %', NEW.user_id, kept
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER profiles_closed_completely
  AFTER UPDATE OF "closed_at" ON "profiles"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW
  WHEN (OLD.closed_at IS NULL AND NEW.closed_at IS NOT NULL)
  EXECUTE FUNCTION profiles_closed_completely();--> statement-breakpoint
-- Hand-edited: a closed account cannot sign in (#140): no session is created for it and no sign-in
-- method added — whatever better-auth is handed (a password-reset link sent before the closure
-- would otherwise create a credential for it). The profile row is read FOR KEY SHARE, which waits
-- for a closure in flight (it holds the row FOR UPDATE) and then reads its closed_at, so a sign-in
-- racing the closure cannot leave a session behind it. Runs as the invoker: buddha_app may UPDATE
-- profiles, which FOR KEY SHARE asks for.
CREATE FUNCTION refuse_closed_account_sign_in() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  closed timestamptz;
BEGIN
  SELECT "closed_at" INTO closed FROM "profiles" WHERE "user_id" = NEW.user_id FOR KEY SHARE;
  IF closed IS NOT NULL THEN
    RAISE EXCEPTION 'account % was closed at %: it signs in no more', NEW.user_id, closed
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER session_refuse_closed_account
  BEFORE INSERT ON "session"
  FOR EACH ROW EXECUTE FUNCTION refuse_closed_account_sign_in();--> statement-breakpoint
CREATE TRIGGER account_refuse_closed_account
  BEFORE INSERT ON "account"
  FOR EACH ROW EXECUTE FUNCTION refuse_closed_account_sign_in();--> statement-breakpoint
-- Hand-edited: nor does a closed account take a new row of what the closure deletes for good
-- (#57-18 «곧바로 지운다») from the writers that take no lock the closure holds — a watch
-- (`market_watches`), a recorded search (`market_searches`; its term row follows it), a 본인확인
-- record (`phone_verifications`) or a code send (`phone_verification_codes` — no text goes out for
-- a closed account), and better-auth's password-reset token naming it (`verification`, below). A
-- request that passed SessionGuard just before the closure committed reaches its insert after it:
-- without this its foreign key check waits for the closure (which updates the `user` row's unique
-- address) and then lets the row in — a watch, a search, or the verified number and real name
-- kept by a closed account, whose UNIQUE number would refuse a re-signup with it (#57-17) — or,
-- landing between the closure's delete and its commit, profiles_closed_completely refuses the
-- closure. As refuse_closed_account_sign_in: the profile row FOR KEY SHARE waits for a closure in
-- flight, so a row written first commits first and the closure's later delete removes it, and a
-- row written later finds the account closed. Raised with the trigger's name as the constraint:
-- the API answers it as the session that ended (UNAUTHENTICATED).
CREATE FUNCTION refuse_closed_account_rows() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  closed timestamptz;
BEGIN
  SELECT "closed_at" INTO closed FROM "profiles" WHERE "user_id" = NEW.user_id FOR KEY SHARE;
  IF closed IS NOT NULL THEN
    RAISE EXCEPTION 'account % was closed at %: % takes no row of it', NEW.user_id, closed,
      TG_TABLE_NAME
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER market_watches_open_account
  BEFORE INSERT ON "market_watches"
  FOR EACH ROW EXECUTE FUNCTION refuse_closed_account_rows();--> statement-breakpoint
CREATE TRIGGER market_searches_open_account
  BEFORE INSERT ON "market_searches"
  FOR EACH ROW EXECUTE FUNCTION refuse_closed_account_rows();--> statement-breakpoint
CREATE TRIGGER phone_verifications_open_account
  BEFORE INSERT ON "phone_verifications"
  FOR EACH ROW EXECUTE FUNCTION refuse_closed_account_rows();--> statement-breakpoint
CREATE TRIGGER phone_verification_codes_open_account
  BEFORE INSERT ON "phone_verification_codes"
  FOR EACH ROW EXECUTE FUNCTION refuse_closed_account_rows();--> statement-breakpoint
-- Hand-edited: the same for better-auth's password-reset token, whose value is the account id
-- (`reset-password:<token>`) — a reset asked just before the closure would otherwise leave one
-- naming the closed account, or fail the closure at its commit. Its other rows (no account id) are
-- not looked at.
CREATE FUNCTION refuse_closed_account_password_reset() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  closed timestamptz;
BEGIN
  SELECT "closed_at" INTO closed FROM "profiles" WHERE "user_id" = NEW.value FOR KEY SHARE;
  IF closed IS NOT NULL THEN
    RAISE EXCEPTION 'account % was closed at %: no password reset names it', NEW.value, closed
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER verification_open_account
  BEFORE INSERT ON "verification"
  FOR EACH ROW WHEN (NEW.identifier LIKE 'reset-password:%')
  EXECUTE FUNCTION refuse_closed_account_password_reset();--> statement-breakpoint
-- Hand-edited: the forfeiture of a closure ('탈퇴 소멸', #57-16) is the closing account's own entry,
-- of its whole balance — CLOSURE_FORFEIT exactly when it refers to the account itself (ref
-- `account_closure`), negative and leaving 0 — and nothing is written for an account after its
-- closure: its ledger ends with the forfeiture (the balance stays 0, so the ledger still sums to it,
-- PLAN 5.6). Deferred, so an entry racing the closure is checked against the closure's commit; the
-- closure itself writes its forfeiture before it marks the profile. Compared as text: the enum value
-- is added in this batch.
CREATE FUNCTION ledger_entries_closed_account() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  closed timestamptz;
BEGIN
  SELECT "closed_at" INTO closed FROM "profiles" WHERE "user_id" = NEW.user_id;
  IF NEW.type::text = 'CLOSURE_FORFEIT' OR NEW.ref_type = 'account_closure' THEN
    IF NOT (NEW.type::text = 'CLOSURE_FORFEIT' AND NEW.ref_type = 'account_closure'
            AND NEW.ref_id = NEW.user_id AND NEW.amount_coin < 0 AND NEW.balance_after_coin = 0
            AND closed IS NOT NULL) THEN
      RAISE EXCEPTION 'ledger entry % is a forfeiture only as the closing account''s own, of its whole balance',
        NEW.id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  ELSIF closed IS NOT NULL THEN
    RAISE EXCEPTION 'account % was closed at %: its ledger takes no entry after the closure',
      NEW.user_id, closed
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER ledger_entries_closed_account
  AFTER INSERT ON "ledger_entries"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION ledger_entries_closed_account();--> statement-breakpoint
-- Hand-edited: a nickname hold never names a closed account (#57-18: the nickname a closure gives
-- up is held «계정과의 연결을 끊은 채»): the closure cuts the link of every hold naming it, and none
-- is handed to it afterwards — an operator's cancellation of a nickname reset (ADR-0081 결과 5,
-- NicknameService's handHoldOver skips a closed member first). FOR KEY SHARE as above.
CREATE FUNCTION nickname_holds_open_account() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  closed timestamptz;
BEGIN
  IF NEW.user_id IS NOT NULL THEN
    SELECT "closed_at" INTO closed FROM "profiles" WHERE "user_id" = NEW.user_id FOR KEY SHARE;
    IF closed IS NOT NULL THEN
      RAISE EXCEPTION 'account % was closed at %: no nickname hold names it', NEW.user_id, closed
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER nickname_holds_open_account
  BEFORE INSERT OR UPDATE OF "user_id" ON "nickname_holds"
  FOR EACH ROW EXECUTE FUNCTION nickname_holds_open_account();--> statement-breakpoint
-- Hand-edited: the one rejection without a deciding admin is the closure's (owner decision
-- 2026-10-23, ADR-0085 결과 5): an account restriction request (#139's four kinds) about a member —
-- the member asked about (`user`), or the member of the restriction a change names
-- (`moderation_action`) — who has closed the account by the decision's instant, with the reason
-- '탈퇴' (ACCOUNT_CLOSURE_DECISION_REASON of @buddha/shared). Migration 0021's triggers keep the rest:
-- only a pending request is decided, once, and its request columns never change.
CREATE FUNCTION approval_requests_closure_rejection() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  member text;
BEGIN
  IF NEW.status = 'rejected' AND NEW.decided_by IS NULL THEN
    IF NEW.kind = 'account_restriction' AND NEW.target_type = 'user' THEN
      member := NEW.target_id;
    ELSIF NEW.kind IN ('account_restriction_shorten', 'account_restriction_lift',
                       'account_restriction_cancel')
          AND NEW.target_type = 'moderation_action' THEN
      SELECT a."user_id" INTO member FROM "moderation_actions" a WHERE a."id"::text = NEW.target_id;
    END IF;
    IF member IS NULL OR NEW.decision_reason IS DISTINCT FROM '탈퇴'
       OR NOT EXISTS (SELECT FROM "profiles"
                       WHERE "user_id" = member AND "closed_at" IS NOT NULL
                         AND "closed_at" <= NEW.decided_at) THEN
      RAISE EXCEPTION 'approval request % is rejected without an admin only by the closure of the member it is about',
        OLD.id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER approval_requests_closure_rejection
  BEFORE UPDATE ON "approval_requests"
  FOR EACH ROW EXECUTE FUNCTION approval_requests_closure_rejection();
